export async function run(ctx) {
  await ctx.registerCheckpoints([
    { id: "prepare", message: "Preparing" },
    { id: "work", message: "Doing the work" },
    { id: "verify", message: "Verifying" },
  ]);
  await ctx.emitCheckpoint("prepare");
  await new Promise((r) => setTimeout(r, 2000));
  await ctx.emitCheckpoint("work");
  await new Promise((r) => setTimeout(r, 2000));
  await ctx.emitCheckpoint("verify");
}

export async function run(ctx) {
  await ctx.registerCheckpoints([
    { id: "prepare", message: "Preparing" },
    { id: "explode", message: "This step always fails" },
  ]);
  await ctx.emitCheckpoint("prepare");
  await new Promise((r) => setTimeout(r, 1000));
  throw new Error("Intentional harness failure");
}

